insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000001e', 'en', null, 'The Science of Cooking', 'Why does a steak brown, an egg set, and mayonnaise thicken? A friendly tour of the chemistry and physics behind everyday cooking — heat, proteins, the Maillard reaction, emulsions, leavening, and flavor. Built from openly-licensed OER Commons material (CC BY).', null, 'daily_life', 30, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000001e', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: what''s happening in your kitchen?', 'quiz', '{"questions":[{"prompt":"An egg white turns from clear to solid white mainly because of…","options":["evaporation of water","protein denaturation and coagulation","caramelization of sugar","the Maillard reaction"],"answer":1,"explanation":"Heat unfolds (denatures) the egg-white proteins, which then bond into a solid network (coagulation)."},{"prompt":"The deep-brown crust on a seared steak is mostly produced by…","options":["the fat burning","the Maillard reaction between amino acids and sugars","water boiling on the surface","protein denaturation alone"],"answer":1,"explanation":"Browning flavor and color come from the Maillard reaction — amino acids reacting with reducing sugars under dry heat."},{"prompt":"Mayonnaise is best described as…","options":["a simple solution","an emulsion of oil droplets suspended in water","a foam of air in fat","a pure suspension of solids"],"answer":1,"explanation":"Mayo is an oil-in-water emulsion: tiny oil droplets held apart in a watery base."},{"prompt":"An emulsifier such as egg-yolk lecithin works because each molecule is…","options":["only water-loving","only oil-loving","both water-loving and oil-loving (amphiphilic)","denser than oil"],"answer":2,"explanation":"Amphiphilic molecules have one end that likes water and one that likes oil, so they coat droplets and keep the two from separating."},{"prompt":"Baking soda makes a batter rise by releasing…","options":["oxygen","carbon dioxide gas","nitrogen","pure steam"],"answer":1,"explanation":"Baking soda (sodium bicarbonate) reacts with acid to release CO2 bubbles that expand the batter."},{"prompt":"Caramelization is the browning of…","options":["proteins","sugars heated on their own","fats","water"],"answer":1,"explanation":"Caramelization is sugar breaking down under heat — distinct from the Maillard reaction, which also needs amino acids."},{"prompt":"\"Searing a steak locks in its juices.\" This is…","options":["true — the crust seals the surface","a myth — searing adds flavor by browning, but does not seal in moisture","true — browned meat is waterproof","true — the crust is completely impermeable"],"answer":1,"explanation":"Classic myth. Seared meat can lose as much (or more) moisture; searing is worth it for Maillard flavor, not for sealing."},{"prompt":"The five basic tastes are sweet, sour, salty, bitter, and…","options":["spicy","umami","cold","crunchy"],"answer":1,"explanation":"Umami is the savory taste of glutamate, found in tomatoes, cheese, mushrooms, and broth. (Spicy is a heat sensation, not a taste.)"}]}'::jsonb, null, 10),
  (2, 'Heat: how cooking transforms food', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how heat moves into food and the main changes it causes. Warm-up: from the diagnostic, why does a thin pancake cook through faster than a thick roast?"},{"heading":"The idea","text":"Heat is just energy that makes molecules move faster. It reaches food three ways: *conduction* (a hot pan touching a steak), *convection* (hot air in an oven or bubbling water carrying heat around), and *radiation* (infrared from a grill or broiler). As food heats, several things happen: proteins *denature* and firm up, starches *gelatinize* and thicken, water *evaporates* (capping the wet surface near 100 °C / 212 °F), and — only once the surface dries and climbs past ~140 °C — *browning* reactions kick in. That last point is why boiled food never browns but roasted food does."},{"heading":"Worked example","text":"Pull a roast from the oven at 55 °C and its center keeps climbing for several minutes — *carryover cooking*. The outer layers are much hotter than the core, and conduction keeps moving that heat inward even off the heat. Chefs rest meat partly for this: yank it a few degrees early and let carryover finish the job so it doesn''t overshoot."},{"heading":"Your turn","text":"Name the dominant heat-transfer mode: (1) toast under a broiler, (2) a potato boiling in water, (3) a burger on a flat cast-iron pan, (4) a convection oven fan roasting vegetables. Answers: (1) radiation, (2) convection, (3) conduction, (4) convection (with some conduction on the tray)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a wet, boiling surface can brown — it can''t, because water caps it near 100 °C, below the ~140 °C browning threshold. Mistake: cranking heat to cook a thick roast faster (you just burn the outside before the center is done). Exit: (a) What surface condition is required before browning starts? (b) What is carryover cooking? Answers: a dry surface above ~140 °C; residual heat conducting inward after food leaves the heat."}]}'::jsonb, 'Three ways heat travels: conduction (contact), convection (moving fluid), radiation (waves).', 12),
  (3, 'Proteins: why eggs and meat cook the way they do', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain denaturation and coagulation, and predict how temperature changes egg and meat texture. Warm-up: why is a hard-boiled egg firm but a raw one runny?"},{"heading":"The idea","text":"Proteins are long chains folded into tidy shapes, held by weak bonds. Heat (or acid, salt, or whisking) breaks those weak bonds so the chains *denature* — unfold like tangled shoelaces. The exposed strands then link to each other and *coagulate* into a solid mesh that traps water. Egg-white proteins begin setting around 60–65 °C; yolk around 65–70 °C. In meat, muscle proteins firm and lose red color from ~50–65 °C, while tough *collagen* shrinks around 60–65 °C and, with long slow moist heat above ~70 °C, melts into silky *gelatin* — the reason a brisket goes from chewy to tender."},{"heading":"Worked example","text":"Want a jammy soft egg vs. a chalky hard one? It''s all temperature. Hold the white just past 63 °C and the yolk stays fluid and bright. Push everything past ~70 °C and the yolk fully sets; overcook and the proteins squeeze so tightly they wring out water and turn rubbery, sometimes greening the yolk edge (iron + sulfur). Gentle heat = tender; aggressive heat = tough and dry."},{"heading":"Your turn","text":"Predict the result: (1) whisking egg whites and adding a pinch of acid, (2) simmering a tough shank for 4 hours, (3) blasting a lean chicken breast on high until 85 °C internal, (4) frying an egg only until the white just sets. Answers: (1) acid helps denature/stabilize the foam (meringue); (2) collagen converts to gelatin — fall-apart tender; (3) proteins over-coagulate and expel water — dry; (4) tender, moist white with a soft yolk."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking \"denatured\" means spoiled or ruined — denaturation is exactly what cooking does on purpose. Mistake: believing meat only cooks at a rolling boil; most proteins set well below 100 °C. Exit: (a) What happens to collagen with long, slow, moist heat? (b) Why does overcooked meat turn dry? Answers: it converts to gelatin (tender); over-coagulated proteins squeeze out their water."}]}'::jsonb, 'Denature = unfold; coagulate = the unfolded strands bond into a solid.', 13),
  (4, 'The Maillard reaction and browning', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the Maillard reaction, tell it apart from caramelization, and set up your pan so food actually browns. Warm-up: why does toast smell nothing like the bread it came from?"},{"heading":"The idea","text":"The *Maillard reaction* is a cascade of reactions between amino acids (from proteins) and *reducing sugars* that really gets going around 140–165 °C (285–330 °F). It builds hundreds of new aroma molecules plus brown pigments called *melanoidins* — the roasted, toasty, meaty smell of seared steak, coffee, bread crust, and fried onions. Crucially it needs a *dry, hot* surface: as long as the surface is wet, water pins the temperature near 100 °C, far below the browning zone. *Caramelization* is a cousin — sugar alone breaking down under heat (~160 °C+) — and gives caramel and toasted-sugar notes without needing protein."},{"heading":"Worked example","text":"Two identical steaks. One goes straight from a wet marinade into a crowded pan; it steams grey and sad — the surface moisture and the crowd of cold meat drop the pan below browning temperature. The other is patted bone-dry, salted, and seared in a hot, roomy pan; it drives off surface water fast, climbs past 140 °C, and builds a deep brown crust. Same meat, opposite result — the difference is dryness and pan temperature."},{"heading":"Your turn","text":"Browning or not, and why: (1) onions sweated with a lid on until translucent, (2) the same onions cooked uncovered, low and slow, until deep brown, (3) chicken simmered in broth, (4) a marshmallow toasted over a flame. Answers: (1) no — trapped steam keeps it wet and cool; (2) yes — Maillard (plus some caramelization of onion sugars); (3) no — wet, capped near 100 °C; (4) yes — the sugary surface browns (mostly caramelization with some Maillard)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling all browning \"caramelization\" — that word is specifically sugar alone; savory browning of protein-rich food is Maillard. Mistake: thinking browning is just \"almost burning\" — burning is different, destructive charring past the flavorful zone. Exit: (a) What two ingredient families drive the Maillard reaction? (b) Why won''t boiled chicken brown? Answers: amino acids and reducing sugars; a wet surface stays near 100 °C, below the browning threshold."}]}'::jsonb, 'Maillard = amino acids + sugars (savory browning). Caramelization = sugars alone.', 13),
  (5, 'Checkpoint 1: heat, proteins, and browning', 'quiz', '{"questions":[{"prompt":"Heat reaching food from a hot pan by direct contact is…","options":["convection","radiation","conduction","evaporation"],"answer":2,"explanation":"Direct contact between two touching materials is conduction."},{"prompt":"A wet food surface cannot brown because water holds it near…","options":["40 °C","100 °C, below the ~140 °C browning threshold","200 °C","300 °C"],"answer":1,"explanation":"Evaporating water caps the surface near 100 °C, too cool for Maillard browning."},{"prompt":"When proteins are heated, they first unfold. This is called…","options":["coagulation","denaturation","gelatinization","emulsification"],"answer":1,"explanation":"Denaturation is the unfolding; coagulation is the bonding that follows."},{"prompt":"Tough collagen in slow-cooked meat becomes tender because it converts to…","options":["starch","gelatin","fat","sugar"],"answer":1,"explanation":"With long, slow, moist heat, collagen turns into gelatin."},{"prompt":"The Maillard reaction is a reaction between reducing sugars and…","options":["water","fats","amino acids","salt"],"answer":2,"explanation":"Amino acids plus reducing sugars — that combination defines the Maillard reaction."},{"prompt":"Overcooked meat turns dry mainly because the proteins…","options":["absorb extra water","over-coagulate and squeeze water out","caramelize","denature too slowly"],"answer":1,"explanation":"Excess heat tightens the protein network so it wrings out its moisture."}]}'::jsonb, null, 8),
  (6, 'Emulsions: mayonnaise, vinaigrette, and why they break', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what an emulsion is, why oil and water normally refuse to mix, and how to rescue a broken sauce. Warm-up: why does a shaken vinaigrette separate again in a minute, but mayonnaise stays thick for days?"},{"heading":"The idea","text":"Oil and water don''t mix because water molecules cling to each other and shove oil out. An *emulsion* forces one into the other as tiny droplets: whisking shears oil into microscopic beads dispersed through water. But droplets want to merge back, so you need an *emulsifier* — an *amphiphilic* molecule with a water-loving end and an oil-loving end that coats each droplet and keeps them apart. Egg-yolk *lecithin* does this in mayonnaise (oil-in-water); mustard and its mucilage help hold a vinaigrette. Without an emulsifier you get a *temporary* emulsion (vinaigrette) that separates; with one you get a *stable* emulsion (mayo)."},{"heading":"Worked example","text":"Why mayo breaks and how to fix it: add the oil too fast, or use cold ingredients, or overshoot the oil-to-yolk ratio, and there isn''t enough emulsifier and whisking to coat every new droplet — the droplets coalesce and the sauce splits into a greasy puddle. The fix: don''t keep whisking the broken mess. Start fresh in a clean bowl with a new egg yolk (or a teaspoon of water/mustard), then slowly whisk the *broken* mixture into it drop by drop. The fresh emulsifier re-coats the droplets and the sauce comes back together."},{"heading":"Your turn","text":"Stable or temporary, and what (if anything) stabilizes it: (1) plain oil and vinegar shaken hard, (2) oil, vinegar, and a spoon of mustard whisked, (3) mayonnaise, (4) hollandaise (egg yolk + butter). Answers: (1) temporary — no emulsifier, separates; (2) more stable — mustard acts as emulsifier; (3) stable — egg-yolk lecithin; (4) stable — egg-yolk lecithin emulsifies the butterfat."},{"heading":"Common mistakes & exit ticket","text":"Mistake: pouring oil into mayo all at once — droplets must be added slowly so each can be coated. Mistake: thinking whisking harder alone fixes a broken emulsion (you need fresh emulsifier). Exit: (a) What property must an emulsifier molecule have? (b) Name the emulsifier in mayonnaise. Answers: it must be amphiphilic (water-loving and oil-loving ends); egg-yolk lecithin."}]}'::jsonb, 'Emulsifier = the go-between that keeps oil and water from separating.', 13),
  (7, 'Leavening and the science of baking', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how baked goods rise and choose the right leavener. Warm-up: what actually makes bread and cake puff up instead of staying dense?"},{"heading":"The idea","text":"*Leavening* means adding gas so a batter or dough expands. Three routes: *biological* — yeast ferments sugars and exhales carbon dioxide (bread); *chemical* — *baking soda* (sodium bicarbonate) reacts with an acid to release CO2, while *baking powder* packs both the soda and a powdered acid in one tin (just add moisture and heat); and *mechanical* — trapped air or steam, like whipped egg whites in a soufflé or the steam that puffs a laminated croissant. Whatever makes the gas, a stretchy network holds it: *gluten* in wheat dough or the protein web in a whipped foam. Heat then sets that structure so the risen shape stays."},{"heading":"Worked example","text":"A recipe uses baking soda but has no acidic ingredient — the soda has nothing to react with, so you get weak lift plus a soapy, metallic taste from the leftover alkaline soda. That''s why soda recipes pair it with buttermilk, yogurt, brown sugar, cocoa, or vinegar. If your batter isn''t acidic, reach for baking powder instead: its built-in acid guarantees the CO2 reaction and leaves no soapy aftertaste."},{"heading":"Your turn","text":"Which leavening type: (1) a sourdough loaf, (2) pancakes made with baking powder, (3) a whipped-egg-white soufflé, (4) puff pastry rising in a hot oven. Answers: (1) biological (yeast); (2) chemical (baking powder); (3) mechanical (trapped air, set by heat); (4) mechanical (steam from the butter layers)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: swapping baking soda for baking powder one-for-one — soda is far stronger and needs acid, powder is milder and self-contained. Mistake: over-mixing wheat batter, which builds too much gluten and turns cake tough. Exit: (a) What gas does yeast produce? (b) Why must baking soda be paired with an acid? Answers: carbon dioxide; without acid it won''t fully react and leaves a soapy, metallic taste."}]}'::jsonb, 'Baking soda needs an acid; baking powder already contains its own acid.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"denaturation","translation":"the unfolding of a protein''s shape by heat, acid, salt, or whisking","example":"Denaturation is why a clear egg white turns opaque as it cooks."},{"term":"Maillard reaction","translation":"browning from amino acids reacting with reducing sugars under dry heat (~140 °C+)","example":"The savory crust on seared steak is the Maillard reaction at work."},{"term":"caramelization","translation":"the browning of sugars heated on their own, without protein","example":"Slowly cooking sugar until amber is pure caramelization."},{"term":"emulsion","translation":"tiny droplets of one liquid dispersed in another it normally won''t mix with","example":"Mayonnaise is an emulsion of oil droplets in water."},{"term":"emulsifier","translation":"an amphiphilic molecule that coats droplets so oil and water stay mixed","example":"Egg-yolk lecithin is the emulsifier that keeps mayo stable."},{"term":"umami","translation":"the savory fifth taste produced by glutamate","example":"Parmesan, tomatoes, and broth are rich in umami."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2: emulsions, leavening, and flavor', 'quiz', '{"questions":[{"prompt":"An emulsifier keeps oil and water mixed because it is…","options":["denser than both","amphiphilic — one end likes water, one likes oil","purely water-loving","chemically inert"],"answer":1,"explanation":"Amphiphilic molecules coat droplets, bridging oil and water."},{"prompt":"The emulsifier in classic mayonnaise comes from…","options":["olive oil","egg-yolk lecithin","vinegar","salt"],"answer":1,"explanation":"Lecithin in egg yolk stabilizes the oil-in-water emulsion."},{"prompt":"The best first step to fix a broken mayonnaise is to…","options":["whisk the broken sauce harder","start with fresh emulsifier and slowly whisk the broken mix into it","add more oil quickly","heat it on the stove"],"answer":1,"explanation":"A fresh yolk (or water/mustard) re-coats the droplets; the broken mix is added slowly."},{"prompt":"Yeast leavens bread by producing…","options":["oxygen","carbon dioxide through fermentation","nitrogen","steam only"],"answer":1,"explanation":"Yeast ferments sugars and releases CO2, which the gluten network traps."},{"prompt":"Baking soda needs which partner to release its gas well?","options":["extra fat","an acid","more flour","salt"],"answer":1,"explanation":"Sodium bicarbonate reacts with acid to release CO2; without acid you get weak lift and a soapy taste."},{"prompt":"Which is one of the five basic tastes?","options":["spicy","umami","crunchy","cool"],"answer":1,"explanation":"Umami (savory) is a basic taste; spicy is a heat sensation, not a taste."}]}'::jsonb, null, 8),
  (10, 'Applied project: explain the science behind a dish you cook', 'writing', '{"sections":[{"heading":"The task","text":"Pick one dish you actually make — scrambled eggs, a seared steak, a vinaigrette, pancakes, caramelized onions, anything. In a few short paragraphs, explain the science behind why it works, using the concepts from this course. You''re not writing a recipe; you''re narrating the chemistry and physics happening in the pan."},{"heading":"Milestones","text":"1) Name the dish and the key transformation you want (e.g. browned crust, fluffy rise, thick sauce). 2) Identify at least two mechanisms at play — choose from heat transfer, denaturation/coagulation, the Maillard reaction or caramelization, emulsification, or leavening. 3) Explain one specific technique in the recipe in scientific terms (e.g. \"I pat the meat dry so the surface can pass 140 °C and brown\"). 4) Describe one common failure and its scientific cause (e.g. a split sauce, a dense cake, rubbery eggs) and how you''d prevent it."},{"heading":"Self-check rubric","text":"✔ You named at least two correct mechanisms and used the right terms. ✔ You linked a real technique to the science, not just \"because the recipe says so.\" ✔ Your failure explanation identifies the actual cause (e.g. over-coagulated protein, an emulsion with too little emulsifier, soda without acid). ✔ Someone could read it and cook the dish better because they now understand *why*. If all four are true, you''re officially cooking like a scientist."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000001e' and l.position = v.pos
);
